const p=$input.first().json;
const screenDays=[
{day:'Mon',activeHours:8.6,idleHours:.8,afterHours:1.2,apps:{'VS Code':3.2,'Chrome':2.4,'Teams':1.8,'Other':1.2}},
{day:'Tue',activeHours:9.1,idleHours:.6,afterHours:1.5,apps:{'VS Code':3.5,'Chrome':2.1,'Teams':2.3,'Other':1.2}},
{day:'Wed',activeHours:8.9,idleHours:.7,afterHours:1.4,apps:{'VS Code':3,'Chrome':2.5,'Teams':2.2,'Other':1.2}},
{day:'Thu',activeHours:9.4,idleHours:.5,afterHours:1.8,apps:{'VS Code':3.6,'Chrome':2.2,'Teams':2.4,'Other':1.2}},
{day:'Fri',activeHours:8.2,idleHours:1,afterHours:.9,apps:{'VS Code':2.8,'Chrome':2,'Teams':2.1,'Other':1.3}},
{day:'Sat',activeHours:2.1,idleHours:.3,afterHours:2.1,apps:{'VS Code':.8,'Chrome':.7,'Teams':.3,'Other':.3}},
{day:'Sun',activeHours:.8,idleHours:.2,afterHours:.8,apps:{'VS Code':.2,'Chrome':.3,'Teams':.1,'Other':.2}}];
return [{json:{...p,screenDays,dataSource:'GENERATED SAMPLE ACTIVITY DATA'}}];

const d=$input.first().json, sum=(a,k)=>a.reduce((s,x)=>s+Number(x[k]||0),0);
const active=sum(d.screenDays,'activeHours'),idle=sum(d.screenDays,'idleHours'),after=sum(d.screenDays,'afterHours');
const meetings=sum(d.calendarDays,'meetings'),meetingHours=sum(d.calendarDays,'meetingHours'),backToBack=sum(d.calendarDays,'backToBack');
const apps={}; for(const day of d.screenDays) for(const [k,v] of Object.entries(day.apps)) apps[k]=(apps[k]||0)+v;
const metrics={totalActiveScreenHours:+active.toFixed(1),averageActiveScreenHoursPerDay:+(active/7).toFixed(1),totalIdleHours:+idle.toFixed(1),afterHoursScreenHours:+after.toFixed(1),totalMeetings:meetings,totalMeetingHours:+meetingHours.toFixed(1),backToBackMeetingBlocks:backToBack,applicationUsageHours:Object.fromEntries(Object.entries(apps).map(([k,v])=>[k,+v.toFixed(1)]))};
return [{json:{...d,metrics}}];

const d=$input.first().json,m=d.metrics; let score=0; const reasons=[];
if(m.averageActiveScreenHoursPerDay>=8){score+=20;reasons.push('Average active screen time is at least 8 hours per day.');}
if(m.totalMeetingHours>=20){score+=20;reasons.push('Meeting time reached 20 hours or more during the week.');}
if(m.backToBackMeetingBlocks>=10){score+=15;reasons.push('Frequent back-to-back meeting blocks were recorded.');}
if(m.afterHoursScreenHours>=5){score+=20;reasons.push('Work-related screen activity occurred after typical hours.');}
if(m.totalIdleHours<5){score+=10;reasons.push('Recorded idle time was relatively low.');}
const level=score>=60?'HIGH':score>=40?'MODERATE':'LOW';
if(!reasons.length)reasons.push('No configured workload indicator was crossed.');
return [{json:{...d,risk:{score,level,reasons,disclaimer:'Illustrative workload-pattern indicator; not a clinical burnout diagnosis.'}}}];

const d = $input.first().json;
const context = {
  employee: { name: d.employeeName, department: d.department, period: d.reportPeriod },
  dataSource: d.dataSource || 'Generated sample activity data',
  metrics: d.metrics,
  baselineRisk: d.risk
};
const system = `You are the analytical engine for Silent Burnout Sentinel. Assess workload patterns, not a person's medical or psychological condition. Never diagnose burnout. Use only the supplied metrics. Treat the data as illustrative generated sample data. Return valid JSON only with this schema: {"riskScore":0,"riskLevel":"LOW|MODERATE|HIGH","assessmentSummary":"...","keyFindings":["..."],"recommendations":["..."],"confidenceNote":"..."}. Score 0-100. Explain uncertainty. Avoid alarmist language. Recommendations should be practical and supportive.`;
return [{json:{...d, aiRequest:{model:'gpt-4o-mini',messages:[{role:'system',content:system},{role:'user',content:'Assess these workload metrics:\\n'+JSON.stringify(context)}],temperature:0.2,response_format:{type:'json_object'}}}}];

const original = $('07 - Prepare AI Assessment Context').first().json;
const response = $input.first().json || {};
const body = response.body && typeof response.body === 'object' ? response.body : response;
let parsed = null;
let aiError = null;
try {
  const content = body.choices?.[0]?.message?.content;
  if (!content) throw new Error(body.error?.message || response.error?.message || 'No AI response returned');
  parsed = JSON.parse(String(content).replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch (e) { aiError = e.message; }

const m = original.metrics;
const fallbackReasons = [];
let fallbackScore = 0;
if (m.averageActiveScreenHoursPerDay >= 8) { fallbackScore += 20; fallbackReasons.push('Average active screen time is at least 8 hours per day.'); }
if (m.totalMeetingHours >= 20) { fallbackScore += 20; fallbackReasons.push('Meeting time reached 20 hours or more during the week.'); }
if (m.backToBackMeetingBlocks >= 10) { fallbackScore += 15; fallbackReasons.push('Frequent back-to-back meeting blocks were recorded.'); }
if (m.afterHoursScreenHours >= 5) { fallbackScore += 20; fallbackReasons.push('After-hours screen activity is elevated.'); }
if (m.totalIdleHours < 5) { fallbackScore += 10; fallbackReasons.push('Recorded idle time is relatively low.'); }
const fallbackLevel = fallbackScore >= 60 ? 'HIGH' : fallbackScore >= 40 ? 'MODERATE' : 'LOW';

const validLevel = ['LOW','MODERATE','HIGH'].includes(String(parsed?.riskLevel || '').toUpperCase());
const score = Number.isFinite(Number(parsed?.riskScore)) ? Math.max(0,Math.min(100,Math.round(Number(parsed.riskScore)))) : fallbackScore;
const level = validLevel ? String(parsed.riskLevel).toUpperCase() : fallbackLevel;
const findings = Array.isArray(parsed?.keyFindings) ? parsed.keyFindings : fallbackReasons;
const recs = Array.isArray(parsed?.recommendations) ? parsed.recommendations : [];
return [{json:{
 ...original,
 aiAssessment:{
  used: !!parsed,
  engine: parsed ? 'OpenAI GPT-4o-mini' : 'Built-in rule-based fallback',
  summary: String(parsed?.assessmentSummary || (aiError ? 'AI analysis was unavailable; the workflow used its transparent fallback rules.' : 'Assessment generated from workload indicators.')),
  keyFindings: findings,
  recommendations: recs,
  confidenceNote: String(parsed?.confidenceNote || 'This is a limited assessment based on the available activity metrics.'),
  error: aiError
 },
 risk:{score,level,reasons:findings.length?findings:fallbackReasons,disclaimer:'Workload-pattern indicator only; not a clinical burnout diagnosis.'}
}}];

const d=$input.first().json;
const aiTips=Array.isArray(d.aiAssessment?.recommendations)?d.aiAssessment.recommendations:[];
const fallback=[];
const m=d.metrics;
if(m.averageActiveScreenHoursPerDay>=8)fallback.push('Schedule short screen breaks and protected time away from the computer.');
if(m.totalMeetingHours>=20)fallback.push('Review recurring meetings and shorten meetings without a clear purpose.');
if(m.backToBackMeetingBlocks>=10)fallback.push('Add 10–15 minute buffers between meetings.');
if(m.afterHoursScreenHours>=5)fallback.push('Review workload boundaries and reduce routine after-hours work.');
if(m.totalIdleHours<5)fallback.push('Plan regular breaks during the workday.');
if(!fallback.length)fallback.push('Maintain healthy routines and continue reviewing workload trends.');
const recommendations=[...new Set([...aiTips,...fallback])].slice(0,8);
return [{json:{...d,recommendations}}];

const d=$input.first().json,m=d.metrics;
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const apps=Object.entries(m.applicationUsageHours).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v} hrs</td></tr>`).join('');
const reasons=d.risk.reasons.map(x=>`<li>${esc(x)}</li>`).join(''),tips=d.recommendations.map(x=>`<li>${esc(x)}</li>`).join('');
const aiSummary=esc(d.aiAssessment?.summary||'AI summary unavailable');
const aiFindings=(d.aiAssessment?.keyFindings||[]).map(x=>`<li>${esc(x)}</li>`).join('');
const aiEngine=esc(d.aiAssessment?.engine||'Assessment engine');
const confidence=esc(d.aiAssessment?.confidenceNote||'');
const emailSubject=`Silent Burnout Sentinel | ${d.risk.level} Workload Assessment`;
const emailHtml=`<div style="font-family:Arial,sans-serif;max-width:700px;margin:auto;color:#222"><h2>Silent Burnout Sentinel</h2><p>Hello ${esc(d.employeeName)},</p><p>Here is your ${esc(d.reportPeriod)} workload assessment for ${esc(d.department)}.</p><h2>Risk indicator: ${d.risk.level} (${d.risk.score}/100)</h2><p><b>Data source notice:</b> This report uses generated sample activity data. It has not collected activity from your computer or connected calendar. OpenAI analyzes the generated metrics and produces the assessment.</p><h3>Screen activity</h3><ul><li>Active screen time: ${m.totalActiveScreenHours} hours</li><li>Daily average: ${m.averageActiveScreenHoursPerDay} hours</li><li>Idle time: ${m.totalIdleHours} hours</li><li>After-hours activity: ${m.afterHoursScreenHours} hours</li></ul><h3>Application usage</h3><table border="1" cellpadding="7">${apps}</table><h3>Calendar workload</h3><ul><li>Meetings: ${m.totalMeetings}</li><li>Meeting hours: ${m.totalMeetingHours}</li><li>Back-to-back meeting blocks: ${m.backToBackMeetingBlocks}</li></ul><h3>AI workload assessment</h3><p><b>Analysis engine:</b> ${aiEngine}</p><p>${aiSummary}</p><h4>AI findings</h4><ul>${aiFindings||reasons}</ul><p><small>${confidence}</small></p><h3>Indicators</h3><ul>${reasons}</ul><h3>Recommendations</h3><ul>${tips}</ul><hr><small>${esc(d.risk.disclaimer)}</small></div>`;
return [{json:{...d,emailSubject,emailHtml}}];
